const byId=id=>document.getElementById(id);
const statuses={PROSPECT:'Prospect',QUALIFIE:'Qualifié',PROPOSITION:'Proposition',NEGOCIATION:'Négociation',GAGNE:'Gagné',EN_MISSION:'En mission',TERMINE:'Terminé',PERDU:'Perdu'};
const fields=['company','contact','email','title','mode','skills','consultant_id','next_action','followup','notes','status'];
let token='',page=1,total=0,editing=null,epoch=0,lookupEpoch=0;
const editor=byId('editor'),consultant=byId('consultant');
function option(value,label){const o=document.createElement('option');o.value=value;o.textContent=label;return o}
for(const [value,label] of Object.entries(statuses))for(const id of ['editor-status','status'])byId(id).append(option(value,label));
function notice(message){byId('notice').textContent=message}
async function api(path,options={}){const r=await fetch('/api/admin/'+path,{...options,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
function reset(){lookupEpoch++;editing=null;editor.reset();consultant.replaceChildren(option('','Aucun'));byId('form-title').textContent='Nouvelle opportunité'}
function cell(row,value){const td=document.createElement('td');td.textContent=value;row.append(td);return td}
async function lookup(){const current=++lookupEpoch;const q=byId('consultant-search').value;const d=await api('consultants?'+new URLSearchParams({q,status:'DISPONIBLE'}));if(current!==lookupEpoch||!token)return;const prior=consultant.selectedOptions[0];consultant.replaceChildren(option('','Aucun'));if(prior&&prior.value)consultant.append(option(prior.value,prior.textContent));for(const p of d.items)if(!Array.from(consultant.options).some(o=>o.value===p.id))consultant.append(option(p.id,p.name+' — '+p.role));if(prior)consultant.value=prior.value;notice(d.total>25?'25 résultats affichés : précisez la recherche.':d.total+' consultant(s) disponible(s).')}
byId('find-consultant').onclick=async()=>{try{await lookup()}catch(e){notice(e.message)}};
async function load(){const current=++epoch;const d=await api('crm?'+new URLSearchParams({q:byId('search').value,status:byId('status').value,page}));if(current!==epoch||!token)return;total=d.total;byId('counts').replaceChildren();byId('rows').replaceChildren();for(const [value,label] of Object.entries(statuses)){const box=document.createElement('div');box.className='count';const n=document.createElement('strong');n.textContent=d.counts[value]||0;box.append(n,document.createTextNode(label));byId('counts').append(box)}
for(const item of d.items){const tr=document.createElement('tr');const profile=cell(tr,item.company);const sub=document.createElement('small');sub.textContent=item.title+' · '+item.mode;profile.append(sub);cell(tr,item.consultant_name?item.consultant_name+' ('+item.consultant_status+')':'Non affecté');const relance=cell(tr,item.followup||'À préciser');const action=document.createElement('small');action.textContent=item.next_action;relance.append(action);const now=new Date();if(item.followup&&Date.parse(item.followup)<Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())&&!['TERMINE','PERDU'].includes(item.status))relance.className='deadline-late';cell(tr,statuses[item.status]);const b=document.createElement('button');b.textContent='Modifier';b.onclick=()=>{reset();editing=item;if(item.consultant_id)consultant.append(option(item.consultant_id,item.consultant_name||'Profil indisponible'));for(const f of fields)editor.elements[f].value=item[f];byId('form-title').textContent='Modifier l’opportunité';editor.scrollIntoView({block:'start'})};cell(tr,'').append(b);byId('rows').append(tr)}
if(!d.items.length){const tr=document.createElement('tr');cell(tr,'Aucune opportunité.').colSpan=5;byId('rows').append(tr)}byId('pages').textContent='Page '+page+' · '+total+' opportunité(s)';byId('prev').disabled=page===1;byId('next').disabled=page*25>=total}
async function refresh(){try{await load()}catch(e){notice(e.message)}}
byId('login-form').onsubmit=async e=>{e.preventDefault();token=byId('token').value;byId('token').value='';page=1;try{await Promise.all([load(),loadCatalogue()]);byId('login').hidden=true;byId('workspace').hidden=false;notice('Connecté.')}catch(e){token='';notice(e.message)}};
byId('logout').onclick=()=>{epoch++;token='';reset();byId('rows').replaceChildren();byId('counts').replaceChildren();byId('catalogue-rows').replaceChildren();byId('workspace').hidden=true;byId('login').hidden=false;notice('Déconnecté.')};
editor.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(editor));const target=editing;if(target)data.version=target.version;byId('save').disabled=true;try{await api(target?'crm/'+encodeURIComponent(target.id):'crm',{method:target?'PATCH':'POST',body:JSON.stringify(data)});if(token){reset();page=1;await load();notice('Opportunité enregistrée.')}}catch(e){notice(e.message)}finally{byId('save').disabled=false}};
byId('cancel').onclick=reset;byId('filter').onsubmit=e=>{e.preventDefault();page=1;refresh()};byId('prev').onclick=()=>{if(page>1){page--;refresh()}};byId('next').onclick=()=>{if(page*25<total){page++;refresh()}};

async function loadCatalogue(){const current=token,d=await api('crm/catalogue');if(!token||current!==token)return;const root=byId('catalogue-rows');root.replaceChildren();for(const x of d.items){const tr=document.createElement('tr');for(const k of ['name','sector','status','scope','conditions'])cell(tr,x[k]);root.append(tr)}}
